// 📁 src/LoginPage.js
import React, { useState } from 'react';
import './LoginPage.css';

const LoginPage = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  // Mock form submission handler (design only)
  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form data:', { username, password });
  };

  return (
    <div className="login-container">
      <h1 className="login-title">Issue Management System</h1>
      
      <form onSubmit={handleSubmit} className="login-form">
        <div className="input-group">
          <label htmlFor="username">Username</label>
          <input
            id="username"
            type="text"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            className="login-input"
            required
          />
        </div>
        
        <div className="input-group">
          <label htmlFor="password">Password</label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="login-input"
            required
          />
        </div>

        <button type="submit" className="login-button">
          Login
        </button>
      </form>

      <div className="login-links">
        <a href="#forgot" className="login-link">Forgot password?</a>
        <span className="login-text">No account? <a href="#contact" className="login-link">Contact admin</a></span>
      </div>
    </div>
  );
};

export default LoginPage;
